# ------------------------------------------------------------------------------
# Helper: simple retry wrapper using ApiClient from conftest
# ------------------------------------------------------------------------------

def _send_with_retries(api_client, endpoint: str, params: Dict[str, Any], retry_count: int, retry_statuses: List[int]):
    """
    Send GET request with basic retry strategy for transient failures.
    This uses the ApiClient provided by conftest.py.
    """
    attempts = 0
    last_response = None
    while attempts <= retry_count:
        last_response = api_client.get(endpoint=endpoint, params=params)
        if last_response is not None and last_response.status_code not in retry_statuses:
            return last_response
        attempts += 1
    return last_response


